// ---- Build Prompt (Versuch 1) ----
const payload = ($('Webhook').first().json.body) || $('Webhook').first().json || {};
const difficulty = ["easy","medium","hard"].includes(payload.difficulty) ? payload.difficulty : "medium";
const ROUNDS = 2; // fix, unabhaengig von Schwierigkeit

const SUBTLETY = {
  easy:   "Der Unterschied zwischen starker und schwacher Antwort darf deutlich sein.",
  medium: "Die schwache Antwort soll auf den ersten Blick brauchbar wirken.",
  hard:   "Die schwache Antwort soll sehr ueberzeugend klingen und nur bei genauem Hinsehen als inhaltsleer auffallen."
};
const learningGoal = payload.learningGoal === "other"
  ? (payload.learningGoalCustom || "Allgemeines Finance-Thema")
  : (payload.learningGoal || "Allgemeines Finance-Thema");
const techLabel   = payload.technologyLabel || payload.technologyCustom || "KI-Technologie";
const techContext = payload.technologyWhatsNew ? ("Kontext zur Technologie: " + payload.technologyWhatsNew) : "";

const systemPrompt = `Du bist Spiel-Generator fuer "Prompt Arena"-Challenges der Lufthansa Finance Training Academy. Zielgruppe: eine Controllerin ohne KI-Vorwissen. Sie soll lernen, eine substanzielle KI-Antwort von einer plausibel klingenden, aber inhaltsleeren zu unterscheiden.

Gib AUSSCHLIESSLICH valides JSON zurueck, KEINE Markdown-Code-Bloecke, exakt in diesem Format:
{ "rounds": [ ${ROUNDS} Runden-Objekte ] }

Jede Runde:
{
 "taskDescription": "<deutsche Aufgabe/Frage, 1-2 Saetze, die jemand an eine KI stellt>",
 "systemContext": "<deutscher Kontext MIT konkreten Fakten: Betraege, Ziele, Perioden, Kennzahlen. Dagegen wird geantwortet.>",
 "strong": { "text": "<die inhaltlich STARKE Antwort>", "note": "<warum stark>" },
 "weak":   { "text": "<die plausible, aber INHALTSLEERE Antwort>", "note": "<warum schwach>" }
}

HARTE REGELN:
- systemContext MUSS mindestens eine konkrete Zahl/Kennzahl enthalten (der Grounding-Traeger).
- strong.text nutzt die Fakten aus systemContext konkret (nennt Zahlen, Ziel, Kontextfaktor) und beantwortet die Aufgabe substanziell.
- weak.text ist pauschal und nichtssagend (keine Zahlen, kein Faktenbezug), aber NICHT sachlich falsch und NICHT erfunden. Der Unterschied ist SUBSTANZ, nicht Korrektheit. (Sonst waere es ein Halluzinations-Spiel.)
- strong und weak beziehen sich auf DIESELBE Aufgabe und duerfen sich inhaltlich nicht widersprechen.
- strong.text und weak.text duerfen NICHT identisch sein.
- Beide note-Felder nicht leer.
- Antworte nur mit dem JSON-Objekt.
- ${SUBTLETY[difficulty]}

Schwierigkeit: ${difficulty}. Lernziel: ${learningGoal}. Technologie-Bezug: ${techLabel}. ${techContext}`;

const userPrompt = `Erzeuge jetzt ${ROUNDS} Prompt-Arena-Runden zum Lernziel "${learningGoal}" mit Bezug zur Technologie "${techLabel}", Schwierigkeit "${difficulty}". Gib ausschliesslich das JSON im vorgegebenen Format zurueck.`;

const llm_body = {
  model: "OpenAI GPT OSS 120b KI:Inferenz.nrw",
  messages: [{ role:"system", content: systemPrompt }, { role:"user", content: userPrompt }],
  temperature: 0.6,
  max_tokens: 3000
};
return [{ json: { llm_body, attempt: 1, difficulty, rounds_expected: ROUNDS, payload } }];

// ---- Process & Validate (Versuch 1) ----
const resp = $json;
const bp = $('Build Prompt').first().json;
const payload = bp.payload;
const expected = bp.rounds_expected || 2;
const attempt = 1;

function fail(errors, raw){ return [{ json:{ valid:false, errors, rounds:null, payload,
  meta:{ attempt, model: bp.llm_body.model }, raw } }]; }

let content = "";
try { content = resp.choices[0].message.content; }
catch(e){ return fail(["LLM-Antwort ohne choices/content"], resp); }
const usage = resp.usage || null;

let data;
try {
  const cleaned = String(content).replace(/```json/gi,"").replace(/```/g,"").trim();
  const s = cleaned.indexOf("{"), e = cleaned.lastIndexOf("}");
  data = JSON.parse(s!==-1 && e!==-1 ? cleaned.slice(s,e+1) : cleaned);
} catch(e){ return fail(["LLM-Ausgabe ist kein valides JSON (evtl. abgeschnitten -> max_tokens): " + e.message], content); }

const errors = [];
const rounds = Array.isArray(data.rounds) ? data.rounds : [];
if (rounds.length !== expected) errors.push("rounds: erwartet " + expected + ", erhalten " + rounds.length);

rounds.forEach((r,i)=>{
  const n = "Runde " + (i+1) + ": ";
  if (!r || typeof r !== "object"){ errors.push(n + "kein Objekt"); return; }
  if (!r.taskDescription || !String(r.taskDescription).trim()) errors.push(n + "taskDescription leer");
  if (!r.systemContext   || !String(r.systemContext).trim())   errors.push(n + "systemContext leer");
  else if (!/\d/.test(String(r.systemContext)))                errors.push(n + "systemContext ohne konkrete Zahl (kein Grounding)");
  const st = r.strong || {}, wk = r.weak || {};
  if (!st.text || !String(st.text).trim()) errors.push(n + "strong.text leer");
  if (!wk.text || !String(wk.text).trim()) errors.push(n + "weak.text leer");
  if (!st.note || !String(st.note).trim()) errors.push(n + "strong.note leer");
  if (!wk.note || !String(wk.note).trim()) errors.push(n + "weak.note leer");
  if (st.text && wk.text && String(st.text).trim() === String(wk.text).trim()) errors.push(n + "strong und weak identisch");
});

if (errors.length) return fail(errors, content);

const clean = rounds.map(r => ({
  taskDescription: String(r.taskDescription).trim(),
  systemContext:   String(r.systemContext).trim(),
  strong: { text: String(r.strong.text).trim(), note: String(r.strong.note).trim() },
  weak:   { text: String(r.weak.text).trim(),   note: String(r.weak.note).trim() }
}));

return [{ json: { valid:true, errors:[], rounds: clean, payload,
  meta:{ attempt, model: bp.llm_body.model, tokens: usage }, raw:null } }];

// ---- Build Repair Prompt (Versuch 2) ----
const prev = $('Process & Validate 1').first().json;
const bp = $('Build Prompt').first().json;
const errors = prev.errors || [];

const repairSystem = bp.llm_body.messages[0].content;
const repairUser = "Dein vorheriger Versuch war UNGUELTIG. Zu behebende Fehler:\n- "
  + errors.join("\n- ")
  + "\n\nDein vorheriger (fehlerhafter) Output:\n" + JSON.stringify(prev.raw)
  + "\n\nKorrigiere GENAU diese Fehler und gib erneut AUSSCHLIESSLICH das valide JSON im vorgegebenen Format zurueck.";

const llm_body = {
  model: bp.llm_body.model,
  messages: [{ role:"system", content: repairSystem }, { role:"user", content: repairUser }],
  temperature: 0.2,
  max_tokens: 3000
};
return [{ json: { llm_body, attempt:2, difficulty: bp.difficulty, rounds_expected: bp.rounds_expected, payload: bp.payload } }];

// ---- Process & Validate (Versuch 2) ----
const resp = $json;
const bp = $('Build Prompt').first().json;
const payload = bp.payload;
const expected = bp.rounds_expected || 2;
const attempt = 2;

function fail(errors, raw){ return [{ json:{ valid:false, errors, rounds:null, payload,
  meta:{ attempt, model: bp.llm_body.model }, raw } }]; }

