try { content = resp.choices[0].message.content; }
catch(e){ return fail(["LLM-Antwort ohne choices/content"], resp); }
const usage = resp.usage || null;

let data;
try {
  const cleaned = String(content).replace(/```json/gi,"").replace(/```/g,"").trim();
  const s = cleaned.indexOf("{"), e = cleaned.lastIndexOf("}");
  data = JSON.parse(s!==-1 && e!==-1 ? cleaned.slice(s,e+1) : cleaned);
} catch(e){ return fail(["LLM-Ausgabe ist kein valides JSON (evtl. abgeschnitten -> max_tokens): " + e.message], content); }

const errors = [];
const rounds = Array.isArray(data.rounds) ? data.rounds : [];
if (rounds.length !== expected) errors.push("rounds: erwartet " + expected + ", erhalten " + rounds.length);

rounds.forEach((r,i)=>{
  const n = "Runde " + (i+1) + ": ";
  if (!r || typeof r !== "object"){ errors.push(n + "kein Objekt"); return; }
  if (!r.taskDescription || !String(r.taskDescription).trim()) errors.push(n + "taskDescription leer");
  if (!r.systemContext   || !String(r.systemContext).trim())   errors.push(n + "systemContext leer");
  else if (!/\d/.test(String(r.systemContext)))                errors.push(n + "systemContext ohne konkrete Zahl (kein Grounding)");
  const st = r.strong || {}, wk = r.weak || {};
  if (!st.text || !String(st.text).trim()) errors.push(n + "strong.text leer");
  if (!wk.text || !String(wk.text).trim()) errors.push(n + "weak.text leer");
  if (!st.note || !String(st.note).trim()) errors.push(n + "strong.note leer");
  if (!wk.note || !String(wk.note).trim()) errors.push(n + "weak.note leer");
  if (st.text && wk.text && String(st.text).trim() === String(wk.text).trim()) errors.push(n + "strong und weak identisch");
});

if (errors.length) return fail(errors, content);

const clean = rounds.map(r => ({
  taskDescription: String(r.taskDescription).trim(),
  systemContext:   String(r.systemContext).trim(),
  strong: { text: String(r.strong.text).trim(), note: String(r.strong.note).trim() },
  weak:   { text: String(r.weak.text).trim(),   note: String(r.weak.note).trim() }
}));

return [{ json: { valid:true, errors:[], rounds: clean, payload,
  meta:{ attempt, model: bp.llm_body.model, tokens: usage }, raw:null } }];

// ---- Build Blind Prompt (Inversions-Check, Generierungs-Zeit) ----
const v = $json;                 // valide PV-Ausgabe (aus PV1 ODER PV2)
const rounds = v.rounds;

// pro Runde strong/weak zufaellig auf A/B legen -> Judge sieht keine Labels
const blindRounds = rounds.map((r,i) => {
  const strongIsA = Math.random() < 0.5;
  return {
    round: i+1,
    A: strongIsA ? r.strong.text : r.weak.text,
    B: strongIsA ? r.weak.text : r.strong.text,
    strongLabel: strongIsA ? "A" : "B"     // NUR fuer den Code, NICHT im Prompt
  };
});

const blocks = blindRounds.map(br =>
  `Runde ${br.round}:\nAntwort A: ${br.A}\nAntwort B: ${br.B}`
).join("\n\n");

const system = `Du bist ein strenger Finance-Reviewer. Dir werden pro Runde zwei KI-Antworten (A und B) auf dieselbe Aufgabe gezeigt. Waehle jeweils die inhaltlich FUNDIERTERE Antwort: die, die konkrete Zahlen/Fakten nutzt und die Frage substanziell beantwortet - nicht die pauschalere. Antworte AUSSCHLIESSLICH mit JSON: {"verdicts":[{"round":1,"stronger":"A"}]}`;
const user = `Bewerte diese Runden. Fuer jede Runde: welche Antwort ist staerker?\n\n${blocks}`;

const llm_body = {
  model: v.meta.model || "OpenAI GPT OSS 120b KI:Inferenz.nrw",
  messages: [{ role:"system", content: system }, { role:"user", content: user }],
  temperature: 0,
  max_tokens: 400
};
return [{ json: { llm_body, blindRounds, carry: v } }];

// ---- Process Blind + Assemble DB Row ----
const resp = $json;
const bb = $('Build Blind Prompt').first().json;
const v = bb.carry;
const rounds = v.rounds;
const p = v.payload || {};

// --- Blind-Verdikte parsen (fail-soft: darf NIE den Insert blockieren) ---
let verdicts = [];
try {
  const c = resp.choices[0].message.content;
  const cl = String(c).replace(/```json/gi,"").replace(/```/g,"").trim();
  const s = cl.indexOf("{"), e = cl.lastIndexOf("}");
  const parsed = JSON.parse(s!==-1 && e!==-1 ? cl.slice(s,e+1) : cl);
  verdicts = Array.isArray(parsed.verdicts) ? parsed.verdicts : [];
} catch(e) { verdicts = []; }

let blindPassed = null;            // null = nicht durchfuehrbar (fail-soft -> baseline)
const disagreements = [];
if (verdicts.length === bb.blindRounds.length && verdicts.length > 0) {
  bb.blindRounds.forEach(br => {
    const vd = verdicts.find(x => Number(x.round) === br.round);
    if (!vd || String(vd.stronger).toUpperCase() !== br.strongLabel) disagreements.push(br.round);
  });
  blindPassed = disagreements.length === 0;
}

// --- game_json assemblen: Code vergibt id + qualityRank (strong->1, weak->2) ---
const arenaRounds = rounds.map((r,i) => ({
  id: i+1,
  taskDescription: r.taskDescription,
  systemContext: r.systemContext,
  referenceOutputs: [
    { id:1, text: r.strong.text, qualityRank:1, note: r.strong.note },
    { id:2, text: r.weak.text,   qualityRank:2, note: r.weak.note }
  ]
}));
const game_json = {
  format: "prompt_arena",
  arenaRounds,
  scoring: { maxPoints: arenaRounds.length, passingScore: arenaRounds.length }
};

// Blind-Ergebnis aendert NICHT den Status (kein needs_review-Wert im System) -
// es lebt nur in generation_meta.blindCheck. Status ist immer 'draft', Mensch reviewt eh.
const status = "draft";

const techLabel = p.technologyLabel || p.technologyCustom || "KI";
const goalLabel = p.learningGoal === "other" ? (p.learningGoalCustom || "Finance") : (p.learningGoal || "Finance");
const goalDisplay = p.learningGoal === "other" ? (p.learningGoalCustom || null) : (p.learningGoal || null);

return [{ json: {
  title: `Prompt Arena: ${goalLabel} – ${techLabel}`,
  format: p.gameType || "prompt_arena",
  difficulty: p.difficulty || "medium",
  language: "de",
  learning_objective: goalDisplay,
  game_json,
  status,
  technology_id: (p.technologyId && p.technologyId !== "other") ? p.technologyId : null,
  technology_custom: p.technologyId === "other" ? (p.technologyCustom || null) : null,
  learning_goal: p.learningGoal !== "other" ? p.learningGoal : null,
  learning_goal_custom: p.learningGoal === "other" ? (p.learningGoalCustom || null) : null,
  requested_by: p.requestedBy || null,
  generation_meta: Object.assign({}, v.meta || {}, { blindCheck: { passed: blindPassed, disagreements } }),
  created_at: new Date().toISOString()
}}];
